cat > /tmp/patch.py <<'E'
p="src/messaging/keys.ts"
s=open(p).read()
s=s.replace('import { OrderEventKind } from "../domain/order";','import { createHash } from "crypto";\nimport { OrderEventKind } from "../domain/order";')
s=s.replace('''  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;''','''  const logical = `${KIND_CODE[kind]}.${orderNo}`;
  // mqpub 3.x 는 한 배치 안에서 키의 앞 16바이트가 같으면 뒤쪽을 보지 않고 첫 메시지만 남긴다(조용히 버림).
  // 네임스페이스 바로 뒤에 논리 키의 결정적 해시를 둬 앞 16바이트가 메시지마다 달라지게 한다.
  const h = createHash("sha1").update(`${namespace}.${logical}`).digest("hex").slice(0, 12);
  return `${namespace}.${h}.${logical}`;''')
open(p,"w").write(s)
E
python3 -I /tmp/patch.py && bash test.sh 2>&1 | grep -E "FAIL|failed|passed"; grep -rn keyNamespace src/config.ts

